cargo new words && cd words

// src/main.rs
fn count_words(text: &str) -> usize {
    text.split_whitespace().count()
}

fn main() {
    let text = std::env::args().nth(1).unwrap_or_default();
    println!("{}", count_words(&text));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn counts_words_separated_by_spaces() {
        assert_eq!(count_words("раз два  три"), 3);
    }

    #[test]
    fn empty_text_has_no_words() {
        assert_eq!(count_words(""), 0);
    }
}

cargo run -- "раз два три"
